# --- перенос данных (ТЗ 2.2): старые виды программ → справочник маршрутов; возраст → годы рождения ---
import re  # noqa: E402

OLD_JUMPING = {
    "jumping_clear": "no_time",
    "jumping_clear_time": "clear_speed",
    "jumping_jumpoff": "jumpoff",
    "jumping_two_phases": "two_phases",
    "jumping_two_rounds": "two_rounds",
    "jumping_speed": "speed_handiness",
}
FIRST_VARIANT = {"two_phases": "35.1.5.2", "two_rounds": "34.3.2"}
DEFAULT_TABLE = {"speed_handiness": "C"}


def forward(apps, schema_editor):
    ProgramItem = apps.get_model("tournaments", "ProgramItem")
    TournamentClass = apps.get_model("tournaments", "TournamentClass")
    Tournament = apps.get_model("tournaments", "Tournament")
    Result = apps.get_model("conduct", "Result")
    for t in Tournament.objects.all():
        if t.organizer_name and not t.contact_name:
            t.contact_name = t.organizer_name[:200]
            t.save(update_fields=["contact_name"])
    for p in ProgramItem.objects.all():
        has_results = Result.objects.filter(entry__program_id=p.pk).exists()
        old = p.program_type
        if p.discipline == "jumping":
            key = OLD_JUMPING.get(old)
            if key and not has_results:
                p.program_type, p.variant, p.table = key, FIRST_VARIANT.get(key, ""), DEFAULT_TABLE.get(key, "A")
            else:
                p.program_type = "manual"
            m = re.findall(r"(\d{2,3})\s*см", p.name)
            p.heights = sorted({int(x) for x in m if 40 <= int(x) <= 200})
        elif p.discipline == "dressage":
            p.program_type = "dressage_manual"
        p.save()
    for c in TournamentClass.objects.select_related("program__tournament"):
        year = c.program.tournament.starts_on.year
        if c.max_age:
            c.birth_year_from = year - c.max_age
        if c.min_age:
            c.birth_year_to = year - c.min_age
        if c.rank_requirement:
            c.note = c.rank_requirement[:300]
        c.save()


_removals = [op for op in Migration.operations if isinstance(op, (migrations.RemoveField, migrations.RemoveConstraint))]
Migration.operations = [op for op in Migration.operations if op not in _removals] + [
    migrations.RunPython(forward, migrations.RunPython.noop)
] + _removals
